<?php $title='Pré-check-ins';require __DIR__.'/_top.php';?><div class="page-heading"><div><p class="eyebrow">Chegada e regras</p><h1>Pré-check-ins</h1></div></div><div class="detail-grid"><section class="admin-panel"><h2>Versão das regras</h2><form method="post" action="<?= e(base_url('admin/operacoes/rules-bootstrap')) ?>"><?= csrf_field() ?><button class="admin-secondary">Criar versão inicial em rascunho</button></form><?php foreach($ruleVersions as $rule):?><div class="block-row"><strong>v<?= (int)$rule['version_no'] ?> · <?= e($rule['status']) ?></strong><?php if($rule['status']==='DRAFT'):?><form method="post" action="<?= e(base_url('admin/operacoes/rules-approve')) ?>"><?= csrf_field() ?><input type="hidden" name="version_id" value="<?= (int)$rule['id'] ?>"><button class="admin-primary">Aprovar regras</button></form><?php endif;?></div><?php endforeach;?></section><section class="admin-panel"><h2>Fila de análise</h2><?php if(!$precheckins):?><p class="empty-state">Nenhum pré-check-in iniciado.</p><?php endif;?><?php foreach($precheckins as $pre):?><article class="block-row"><div><strong><?= e($pre['codigo']) ?> · <?= e($pre['nome_cliente']) ?></strong><small><?= e($pre['status']) ?> · <?= (int)$pre['guest_count'] ?>/10 hóspedes · check-in <?= e($pre['checkin']) ?></small></div><?php if(in_array($pre['status'],['SUBMITTED','UNDER_REVIEW','CORRECTION_REQUESTED'],true)):?><form class="row-actions" method="post" action="<?= e(base_url('admin/operacoes/precheckin-review')) ?>"><?= csrf_field() ?><input type="hidden" name="reservation_id" value="<?= (int)$pre['reservation_id'] ?>"><input name="message" placeholder="Motivo se correção/rejeição"><button name="decision" value="approve" class="admin-primary">Aprovar</button><button name="decision" value="correction" class="admin-secondary">Corrigir</button><button name="decision" value="reject" class="admin-danger">Rejeitar</button></form><?php endif;?></article><?php endforeach;?></section></div><?php require __DIR__.'/_bottom.php';?>
